import json
import logging
from pymongo import MongoClient
from flask import Flask, request, jsonify

app = Flask(__name__)
logger = logging.getLogger(__name__)

# MongoDB connection for IoT telemetry storage
MONGO_URI = "mongodb://iot-telemetry-cluster.internal:27017"
client = MongoClient(MONGO_URI)
db = client['iot_platform']
devices_collection = db['devices']
telemetry_collection = db['telemetry']

def validate_device_token(token):
    """Validate device authentication token against device registry"""
    if not token or len(token) < 16:
        return None
    device = devices_collection.find_one({"auth_token": token})
    return device

def sanitize_topic(topic):
    """Basic topic validation - ensures topic follows naming convention"""
    if not topic:
        return None
    # Allow alphanumeric, slashes, hyphens, underscores
    allowed = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789/-_')
    if all(c in allowed for c in topic):
        return topic
    return None

@app.route('/api/v2/devices/messages', methods=['POST'])
def handle_device_message():
    """Process incoming IoT device messages and store telemetry"""
    auth_header = request.headers.get('X-Device-Token')
    device = validate_device_token(auth_header)
    if not device:
        return jsonify({"error": "unauthorized"}), 401

    try:
        payload = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "invalid payload"}), 400

    topic = sanitize_topic(payload.get('topic'))
    if not topic:
        return jsonify({"error": "invalid topic"}), 400

    # Store telemetry data
    telemetry_record = {
        "device_id": device['device_id'],
        "topic": topic,
        "data": payload.get('data', {}),
        "timestamp": payload.get('timestamp')
    }
    telemetry_collection.insert_one(telemetry_record)

    return jsonify({"status": "accepted", "id": str(telemetry_record['_id'])}), 202

@app.route('/api/v2/devices/query', methods=['POST'])
def query_device_telemetry():
    """Query telemetry data for a device - used by fleet management dashboard"""
    auth_header = request.headers.get('X-Device-Token')
    device = validate_device_token(auth_header)
    if not device:
        return jsonify({"error": "unauthorized"}), 401

    try:
        query_params = request.get_json(force=True)
    except Exception:
        return jsonify({"error": "invalid query"}), 400

    # Build query filter from request parameters
    query_filter = {"device_id": device['device_id']}

    # Allow filtering by topic pattern
    if 'topic_filter' in query_params:
        query_filter['topic'] = query_params['topic_filter']

    # Allow filtering by time range
    if 'time_range' in query_params:
        query_filter['timestamp'] = query_params['time_range']

    # Allow filtering by data field conditions
    if 'data_filter' in query_params:
        for key, value in query_params['data_filter'].items():
            query_filter[f'data.{key}'] = value

    try:
        results = list(telemetry_collection.find(
            query_filter,
            {"_id": 0, "device_id": 1, "topic": 1, "data": 1, "timestamp": 1}
        ).limit(100))
    except Exception as e:
        logger.error(f"Query failed: {e}")
        return jsonify({"error": "query failed"}), 500

    return jsonify({"results": results, "count": len(results)}), 200

@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({"status": "healthy"}), 200

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8443)
